using System.Collections.Generic;using UnityEngine;using LighthouseKeepers.Core;
namespace LighthouseKeepers.WatchDemo {
 public sealed class StormPresentation:MonoBehaviour {
  WatchDemoController watch;ParticleSystem dust;AudioSource rattle;Transform head;float nextRattle;Material dustMaterial;readonly List<(Transform t,Quaternion rest)> lamps=new();ParticleSystem rain;float originalRain;AudioSource ocean;float originalOcean;Renderer sea;MaterialPropertyBlock block;
  public static void Create(WatchDemoController w){var p=w.gameObject.AddComponent<StormPresentation>();p.watch=w;}
  void Start(){head=Camera.main.transform;var go=new GameObject("Storm ceiling dust");go.transform.SetParent(transform,false);dust=go.AddComponent<ParticleSystem>();dust.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=dust.main;main.playOnAwake=false;main.loop=false;main.maxParticles=36;main.startLifetime=2.5f;main.startSpeed=.05f;main.startSize=.013f;main.startColor=new Color(.35f,.31f,.24f,.25f);main.gravityModifier=.025f;var emission=dust.emission;emission.enabled=false;var shape=dust.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(2,.02f,2);dustMaterial=new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));dustMaterial.SetFloat("_Surface",1);dustMaterial.SetColor("_BaseColor",new Color(.35f,.31f,.24f,.25f));dust.GetComponent<ParticleSystemRenderer>().sharedMaterial=dustMaterial;dust.GetComponent<ParticleSystemRenderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;rattle=go.AddComponent<AudioSource>();rattle.playOnAwake=false;rattle.spatialBlend=1;rattle.minDistance=1;rattle.maxDistance=8;rattle.volume=.08f;rattle.clip=Resources.Load<AudioClip>("ImmersionAudio/creak");KeeperAudioMix.Route(rattle,"Ambience");var seaObject=GameObject.Find("Original storm ocean presentation");if(seaObject){sea=seaObject.GetComponent<Renderer>();block=new MaterialPropertyBlock();var bounds=sea.localBounds;bounds.Expand(Vector3.up);sea.localBounds=bounds;}foreach(var light in FindObjectsByType<Light>(FindObjectsSortMode.None))if(light.name.Contains("Shielded stair lamp")||light.name.Contains("service lamp"))lamps.Add((light.transform,light.transform.localRotation));
   foreach(var p in FindObjectsByType<ParticleSystem>(FindObjectsSortMode.None))if(p.name.ToLowerInvariant().Contains("rain")){rain=p;originalRain=p.emission.rateOverTime.constant;break;}
   foreach(var a in FindObjectsByType<AudioSource>(FindObjectsSortMode.None))if(a.name.ToLowerInvariant().Contains("ocean")){ocean=a;originalOcean=a.volume;break;}
  }
  void LateUpdate(){int stage=watch.State.Storm.Stage;float strength=(stage-1)/3f;if(stage>=2&&Time.time>nextRattle){nextRattle=Time.time+Random.Range(15f,30f);rattle.transform.position=head.position+Vector3.up*.8f+Vector3.right*1.2f;rattle.volume=.04f*stage;if(rattle.clip)rattle.Play();if(stage>=3&&head.position.y<11.5f&&head.position.z> -10.3f&&new Vector2(head.position.x,head.position.z).magnitude<11)dust.Emit(12);}foreach(var lamp in lamps)if(lamp.t)lamp.t.localRotation=lamp.rest*Quaternion.Euler(0,0,Mathf.Sin((float)watch.State.Elapsed*1.3f)*strength*2);
   if(sea){sea.GetPropertyBlock(block);block.SetFloat("_StormAmplitude",Mathf.Lerp(.08f,.3f,strength));sea.SetPropertyBlock(block);}
   if(rain){var e=rain.emission;e.rateOverTime=originalRain*Mathf.Lerp(.8f,1.15f,strength);}if(ocean)ocean.volume=originalOcean*Mathf.Lerp(.65f,1.2f,strength);
  }
 void OnDestroy(){if(dustMaterial)Destroy(dustMaterial);}
 }
}